"""``generate.encounter_end_legacy_stall`` reproduces 1.4.1, record for record (issue #119)."""
import hashlib
import json
import subprocess
import sys
from datetime import datetime

import pytest

from synthea import compat
from synthea.engine.generator import Generator, GeneratorOptions
from synthea.helpers.config import Config

#: sha256 over every record entry (time, end, codes, value, unit, range, interpretation, name) and the
#: attribute names of 40 persons, seed 20261017, ages 20-70, reference date 2020-01-01, generated by
#: release 1.4.1 (commit 1e478f2) and by 1.4.2 with the setting on. Update only with a changelog note.
EXPECTED_1_4_1 = '86db58594a6ad70629a111e2960ed9f20bf0c2ca54f32087565a3ac2d930bf43'


@pytest.fixture(autouse=True)
def _reset():
    yield
    compat.legacy = False


def _fingerprint(n, legacy):
    c = Config()
    c.load()
    c.set('exporter.fhir.export', False)
    c.set('exporter.baseDirectory', '/tmp/legacy_parity_unused')
    c.set('generate.encounter_end_legacy_stall', legacy)
    o = GeneratorOptions()
    o.population_size = n
    o.seed = 20261017
    o.min_age, o.max_age = 20, 70
    o.reference_date = datetime(2020, 1, 1)
    o.reference_date_explicit = True
    g = Generator(o, config=c)
    h = hashlib.sha256()
    for i in range(n):
        p = g.generate_person(i)
        if p is None:
            continue
        r = p.record
        ph = hashlib.sha256()
        for kind, entries in (('enc', r.encounters), ('cond', r.conditions), ('med', r.medications),
                              ('proc', r.procedures), ('obs', r.observations), ('cp', r.careplans),
                              ('img', r.imaging_studies), ('imm', r.immunizations)):
            for e in entries:
                ph.update(repr((kind, e.time, getattr(e, 'end_time', None),
                                tuple((x.system, str(x.code), x.display) for x in e.codes),
                                repr(getattr(e, 'value', None)), getattr(e, 'unit', None),
                                getattr(e, 'reference_range', None), getattr(e, 'interpretation', None),
                                e.name)).encode())
        ph.update(repr((p.alive, sorted(k for k in p.attributes if not k.startswith('__')))).encode())
        h.update(ph.digest())
    return h.hexdigest()


@pytest.mark.slow
def test_legacy_setting_reproduces_the_1_4_1_records_of_40_persons():
    assert _fingerprint(40, legacy=True) == EXPECTED_1_4_1
    assert compat.legacy is True               # the generator set it


@pytest.mark.slow
@pytest.mark.parametrize('legacy', [False, True])
def test_every_parallel_worker_gets_the_configured_setting(tmp_path, legacy):
    """compat.legacy is process-global; --threads builds one Generator per worker process, so the
    population is identical at 1 and 2 workers in both modes."""
    digests = []
    for threads in (1, 2):
        out = tmp_path / f't{threads}'
        cfg = tmp_path / f'c{threads}.properties'
        cfg.write_text(f'generate.encounter_end_legacy_stall = {str(legacy).lower()}\n')
        subprocess.run([sys.executable, '-m', 'synthea.cli', '--population', '6', '--seed', '5', '--age', '30-60',
                        '--reference-date', '20200101', '--threads', str(threads), '-c', str(cfg),
                        '--output-dir', str(out)], check=True, capture_output=True)
        digests.append(sorted(hashlib.sha256(json.dumps(json.loads(p.read_text('utf-8')), sort_keys=True).encode()).hexdigest()
                              for p in (out / 'fhir').glob('*.json')))
    assert digests[0] == digests[1] and len(digests[0]) == 6
